export function getTheme(themeName: string, customConfig?: any): ThemeConfig {
  const base = THEMES[themeName] || THEMES.ecommerce_1;
  if (!customConfig) return base!;

  return {
    ...base!,
    ...(customConfig.primary ? {
      progressFill: 'bg-[' + customConfig.primary + ']',
      button: 'bg-[' + customConfig.primary + '] text-[' + (customConfig.primaryText || '#fff') + '] rounded-md font-medium hover:opacity-90 transition-opacity',
      optionChipSelected: 'border-2 border-[' + customConfig.primary + '] bg-[' + customConfig.primary + ']/10 text-[' + customConfig.primary + '] rounded-md font-semibold',
      checkboxRowSelected: 'border-2 border-[' + customConfig.primary + '] bg-[' + customConfig.primary + ']/10 text-[' + customConfig.primary + '] rounded-md font-semibold',
      checkboxEl: 'rounded border-gray-300 text-[' + customConfig.primary + '] focus:ring-[' + customConfig.primary + ']',
    } : {}),
  };
}
